boolean isDiagonal(){
    me = players[4]
    found = false
    4.times{
        enemy = players[it]
        if(me.x == enemy.x+1 || me.x == enemy.x-1){
            if(me.y == enemy.y+1 || me.y == enemy.y-1) found = true
        }
    }
    return found
}
boolean isAway(){
    me = players[4]
    for(i=0;i<4;i++){
        if((me.x == players[i].x && (me.y - players[i].y).abs() == 1)
        || (me.y == players[i].y && (me.x - players[i].x).abs() == 1))
            return false
    }
    return true
}
boolean isSafeLined(direction){
    me = new Player(players[4].x, players[4].y)
    switch(direction){
        case RIGHT:
            me.x+=2
            break;
        case DOWN:
            me.y+=2
            break;
        case LEFT:
            me.x-=2
            break;
        case TOP:
            me.y-=2
            break;
    }
    for(i=0;i<4;i++){
        enemy = players[i]
        if(me.x == enemy.x && me.y == enemy.y) return false

    }
    return true
}
boolean isSafeNotLined(direction){
    me = new Player(players[4].x, players[4].y)

    if (direction==RIGHT || direction==LEFT){
        if (direction==RIGHT) me.x += 1
        else me.x -= 1
        for(i=0;i<4;i++){
            enemy = players[i]
            if(me.x == enemy.x && (me.y == enemy.y+1 || me.y == enemy.y-1)) return false
        }
    }
    else
    {
        if (direction==TOP) me.y -= 1
        else me.y += 1
        for(i=0;i<4;i++){
            enemy = players[i]
            if(me.y == enemy.y && (me.x == enemy.x+1 || me.x == enemy.x-1)) return false
        }
    }

    return true
}
boolean notDeadEnd(direction){
    me = new Player(players[4].x, players[4].y)
    switch(direction){
        case RIGHT:
            me.x+=1
            break;
        case DOWN:
            me.y+=1
            break;
        case LEFT:
            me.x-=1
            break;
        case TOP:
            me.y-=1
            break;
    }
    return deadEnds.find{it.x==me.x && it.y==me.y} == null
}
